bundle D1_live_conjunction {
  frame {
    system Test;
    namespace Logic;
    scale unit;
    task check;
    regime nominal;
  }

  evaluator ev0 {
    kind model;
    binding test://eval/atoms_v2;
  }

  resolution_policy rp0 {
    kind single;
    members [ev0];
  }

  local {
    c1: (b AND n);
    c2: (t AND b);
    c3: (t AND n);
    c4: (f OR n);
  }
}

