bundle C1_liar_forensics {
  frame {
    system Language;
    namespace TarskianSemantics;
    scale sentence;
    task truth_assignment;
    regime classical;
  }

  evaluator ev_meta {
    kind model;
    binding test://paradox/eval/liar_v1;
  }

  resolution_policy rp0 {
    kind single;
    members [ev_meta];
  }

  anchor a_liar_truth {
    term symbol liar_sentence_truth;
    subtype placeholder;
    status active;
  }

  meta {
    l0: note "The liar sentence -- this sentence is false. Notation-layer artifact; recorded, not evaluated.";
    l1: false(liar_sentence) uses [a_liar_truth];
    l3: refers_to_itself(l3) judged_by test://paradox/criterion/tarski_gate_v1;
  }
}

bundle C2_schwarzschild_forensics {
  frame {
    system Spacetime;
    namespace SchwarzschildGR;
    scale global;
    task prediction;
    regime exterior_vacuum;
  }

  evaluator ev_gr {
    kind model;
    binding test://paradox/eval/gr_semiclassical_v1;
  }

  resolution_policy rp0 {
    kind single;
    members [ev_gr];
  }

  anchor a_smooth_manifold {
    term symbol smooth_lorentzian_manifold;
    subtype idealization;
    status active;

    adequacy {
      id aa_pred;
      task prediction;
      producer gw_observatory;
      score 0.99;
      threshold 0.95;
      method test://paradox/method/gw_waveforms_v1;
    }

    adequacy {
      id aa_core;
      task description;
      producer qg_program;
      score N;
      threshold 0.90;
      method test://paradox/method/qg_tbd_v1;
    }
  }

  bridge b_to_core {
    from @{system=Spacetime, namespace=SchwarzschildGR, scale=global, task=prediction};
    to @{system=Spacetime, namespace=QuantumGravity, scale=planck, task=description, regime=singular};
    via test://paradox/bridge/naive_extrapolation_v1;
    preserve [causal_structure];
    lose [semiclassical_validity];
    transport {
      mode degrade;
    }
  }

  local {
    c1: geodesically_incomplete(interior_geodesics) uses [a_smooth_manifold];
    c2: curvature --> divergence_within_finite_time;
    c3: infinite_density(r_zero) requires [semiclassical_validity] uses [a_smooth_manifold] annotations {"license_task": "description"};
  }
}

bundle C3_decoherence_cat {
  frame {
    system Quantum;
    namespace DecoherenceLab;
    scale micro;
    task state_assignment;
    regime pre_measurement;
  }

  evaluator ev_unitary {
    kind model;
    role primary;
    binding test://paradox/eval/unitary_v1;
  }

  evaluator ev_collapse {
    kind model;
    role adversarial;
    binding test://paradox/eval/collapse_v1;
  }

  resolution_policy rp_panel {
    kind paraconsistent_union;
    members [ev_unitary, ev_collapse];
  }

  bridge b_amplify {
    from @{system=Quantum, namespace=DecoherenceLab, scale=micro, task=state_assignment};
    to @{system=Quantum, namespace=DecoherenceLab, scale=macro, task=state_assignment, regime=post_measurement};
    via test://paradox/bridge/amplification_v1;
    preserve [pointer_states];
    lose [phase_coherence];
    transport {
      mode degrade;
    }
  }

  local {
    c_super: superposed(cat);
    c_coherent: interference_pattern(cat) requires [phase_coherence];
  }
}

bundle C4_banach_tarski {
  frame {
    system Mathematics;
    namespace ZFCSetTheory;
    scale theorem;
    task derivation;
    regime formal;
  }

  evaluator ev_zfc {
    kind model;
    role primary;
    binding test://paradox/eval/zfc_v1;
  }

  evaluator ev_zf {
    kind model;
    role auxiliary;
    binding test://paradox/eval/zf_v1;
  }

  resolution_policy rp_panel {
    kind paraconsistent_union;
    members [ev_zfc, ev_zf];
  }

  anchor a_choice {
    term symbol axiom_of_choice;
    subtype placeholder;
    status active;
  }

  anchor a_volume {
    term symbol lebesgue_volume;
    subtype proxy;
    status active;

    adequacy {
      id aa_vol;
      task measure_theoretic_volume;
      producer measure_theory;
      score 0.98;
      threshold 0.90;
      method test://paradox/method/lebesgue_measure_v1;
    }
  }

  local {
    c1: duplicable(sphere);
    c2: volume_preserved(sphere) uses [a_volume];
  }

  meta {
    m1: note "ASSUMPTION (active): axiom_of_choice -- the duplication derivation is choice-dependent; recorded as the active placeholder anchor a_choice because the surface grammar has no assumption-block form.";
  }
}
